const screens = [
  {id:'boot', group:'Startup', title:'Boot splash', description:'Rehovot logo, initial load bar, and background service start.'},
  {id:'preload', group:'Startup', title:'TapSum loading', description:'Product mark, game tagline, and animated asset progress.'},
  {id:'menu', group:'Entry', title:'Main menu', description:'Personal best, the three-step sum tape, Play, help, leaderboard, sound, support.'},
  {id:'help', group:'Entry', title:'How to play', description:'Rules overlay with the signed number, running total, place-value taps, and fail conditions.'},
  {id:'leaderboard-loading', group:'Leaderboard', title:'Leaderboard · loading', description:'Loading state while player rows and personal rank are requested.'},
  {id:'leaderboard-empty', group:'Leaderboard', title:'Leaderboard · empty', description:'No score rows and no personal rank available.'},
  {id:'leaderboard-ranked', group:'Leaderboard', title:'Leaderboard · populated', description:'Illustrative top rows, medal assets, scrolling list, and pinned personal score.'},
  {id:'gameplay-start', group:'Gameplay', title:'Gameplay · first round', description:'Round 1, positive target, full timer, place-value controls, tap pips.'},
  {id:'gameplay-warning', group:'Gameplay', title:'Gameplay · timer warning', description:'Later round, minus target, remembered values, pips, and low-time ring.'},
  {id:'pause', group:'Gameplay', title:'Pause sheet', description:'Round and score, resume, sound state, and quit-run action.'},
  {id:'round-success', group:'Gameplay', title:'Round success feedback', description:'Exact match awards +10, celebrates, then proceeds to the next round.'},
  {id:'end-overshoot', group:'Run summary', title:'Game over · too much', description:'Overshoot result with needed/tapped values, recent deltas, rank, and replay.'},
  {id:'end-timeout', group:'Run summary', title:'Game over · time’s up', description:'Timeout result with remaining goal, run score, rounds, and replay.'},
  {id:'end-quit', group:'Run summary', title:'Run ended · quit', description:'Player-ended run summary with score, rank, and return/play actions.'},
  {id:'end-new-best', group:'Run summary', title:'New best · rank pending', description:'New-best celebration with rank still loading.'},
  {id:'end-no-rank', group:'Run summary', title:'Rank unavailable', description:'Summary fallback when a player rank cannot be retrieved.'},
  {id:'support', group:'Platform handoff', title:'Support / donation handoff', description:'Shows the project-owned entry point; native payment UI belongs to the purchases plugin.'},
];
const base = new URL('.', document.currentScript.src);
const route = (id) => `prototype.html?screen=${encodeURIComponent(id)}`;
const query = new URLSearchParams(location.search);
const currentId = query.get('screen') || 'menu';
const currentIndex = Math.max(0, screens.findIndex((s) => s.id === currentId));
const screen = screens[currentIndex] || screens[2];
const asset = (path) => new URL(`../../public/assets/${path}`, base).href;
const go = (id) => `<a class="action-button" href="${route(id)}">${id === 'gameplay-start' ? 'Start a round' : id === 'menu' ? 'Return to menu' : 'Open screen'}</a>`;
const buttonGo = (id, text, cls='') => `<a class="${cls || 'action-button'}" href="${route(id)}">${text}</a>`;
const icon = `<img src="${asset('icons/icon-96.webp')}" alt="">`;
const brandHead = (best='0') => `<header class="game-head"><div class="brand-small">${icon}<span>TapSum</span></div><div class="best-badge">Personal best <strong>${best}</strong></div></header>`;
const utility = `<nav class="utility-row" aria-label="TapSum actions"><button data-action="sound" aria-pressed="false">Sound <span data-sound-state>On</span></button><a href="${route('leaderboard-loading')}">Leaderboard</a><a href="${route('help')}">How to play</a><a href="${route('support')}">Support</a></nav>`;
const tape = (a='+5', b='+3', total='8', cap='RUNNING TOTAL') => `<div class="tape"><div class="tape-topline"><b>TAPE</b><span>${cap}</span></div><div class="tape-step add"><i></i><div><small>Remember this value</small><strong>${a}</strong></div></div><p class="sum-sign" aria-hidden="true">+</p><div class="tape-step take"><i></i><div><small>Add to your total</small><strong>${b}</strong></div></div><p class="sum-sign" aria-hidden="true">=</p><div class="tape-step total"><i></i><div><small>Match it exactly</small><strong>${total}</strong></div></div></div>`;
const playRail = (id='gameplay-start') => `<a class="vertical-play" href="${route(id)}" aria-label="Play, start a round"><span class="arrow">→</span><span>PLAY</span><small>Start a round</small></a>`;
const smallHead = (round, score, pause=true) => `<div class="game-top"><a href="${route('pause')}" aria-label="Pause game" class="pause-trigger">${pause?'Ⅱ':'‹'}</a><strong>ROUND ${round}</strong><span><svg class="star-mark" viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2 2.9 6 6.6.9-4.8 4.7 1.1 6.6-5.8-3.1-5.9 3.1 1.2-6.6-4.8-4.7L9 8z"/></svg> ${score}</span></div>`;
const timer = (n='00:07', warn=false, delta='+8', label='ADD') => `<div class="timer-dial ${warn?'warn':''}"><small>${label}</small><strong>${delta}</strong><span>${n}</span></div>`;
const increments = `<div class="game-actions"><button class="increment" data-tap="10">+10</button><button class="increment" data-tap="100">+100</button><button class="increment" data-tap="1000">+1000</button><button class="increment ones" data-tap="1">+1</button></div>`;
const gameplay = ({round='1',score='0',delta='+8',timerValue='00:07',warn=false,tapCount=2,history=[],label='ADD',success=false}) => `<div class="screen-content game-layout">${smallHead(round,score)}${timer(timerValue,warn,delta,label)}${history.length?`<div class="tape-before"><span>BEFORE</span>${history.map((n)=>`<b class="${n.startsWith('-')?'negative':''}">${n}</b>`).join('')}</div>`:''}<div class="round-progress" aria-label="round progress">${Array.from({length:Math.min(8,+round)},(_,i)=>`<i class="${i<+round-1?'done':''}"></i>`).join('')}</div><div class="taps" data-tap-pips>${Array.from({length:tapCount},()=>'<i></i>').join('')}</div><p class="tap-count" data-tap-count>${tapCount} taps this round</p>${increments}<p class="game-foot">Use the place-value buttons to match the running total exactly.</p>${success?`<div class="overlay-center"><div class="dialog-card success-state"><div class="reason-mark success-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 12 5 5L20 6"/></svg></div><span class="eyelabel">EXACT MATCH</span><h2>Round cleared</h2><p>+10 points · next number is ready</p><a class="action-button primary" href="${route('gameplay-warning')}">Next round →</a></div></div>`:''}</div>`;
function summary({reason,score,round,needed,tapped,recent,best,rank='N/A',newBest=false,compact=false}){
 const kicker=newBest?'NEW BEST!':reason==='overshoot'?'TOO MUCH!':reason==='timeout'?"TIME’S UP!":'RUN ENDED';
 const desc=reason==='quit'?`You stopped at round ${round}.`:reason==='timeout'?`The clock ran out before you reached ${needed}.`:`You needed ${needed}, but tapped ${tapped}.`;
 return `<div class="screen-content summary-screen"><header class="summary-head"><span class="eyelabel ${newBest?'new-best':''}">${kicker}</span><h1>Run complete</h1><p class="supporting">${desc}</p></header>${!compact?`<section class="summary-card"><span class="eyelabel">WHAT HAPPENED</span><div class="comparison"><div><small>YOU NEEDED</small><strong>${needed}</strong></div><span>→</span><div><small>YOU TAPPED</small><strong>${tapped}</strong></div></div><div class="recent"><span>Recent</span>${recent.map((n)=>`<span>${n}</span>`).join('')}</div></section>`:`<section class="summary-card compact-result"><span class="eyelabel">RUN STOPPED</span><p>${desc}</p></section>`}<div class="score-summary"><div class="stat"><small>SCORE</small><strong>${score}</strong></div><div class="stat"><small>ROUNDS CLEARED</small><strong>${Math.max(0,+round-1)}</strong></div></div><div class="rank-row"><span>World rank</span><strong>${rank}</strong></div><p class="best-line ${newBest?'new-best':''}">${newBest?`Your best ever: ${score}`:`Best ${best} · ${Math.max(0,+best - +score)} to beat it`}</p><div class="end-actions">${buttonGo('gameplay-start','Play again','action-button primary')}${buttonGo('menu','Main menu','action-button secondary-button')}</div></div>`;
}
function overlaySheet(title,body,actions,close='menu',cls='') { return `<div class="screen-content overlay-underlay ${cls}">${brandHead('0')}${tape('+5','+3','8')}<div class="modal-shade"><section class="sheet"><button class="close-sheet" data-go="${close}" aria-label="Close overlay">×</button><div class="sheet-handle"></div>${title}${body}${actions}</section></div></div>`; }
function stateContent(id){
 switch(id){
 case 'boot': return `<div class="screen-content startup"><div class="startup-mark" role="img" aria-label="Rehovot logo"></div><p class="startup-caption">A REHOVOT TECH GAME</p><div class="startup-progress"><i style="width:64%"></i></div><span class="muted">Starting up · 64%</span></div>`;
 case 'preload': return `<div class="screen-content startup preload"><div class="brand-large">${icon}<span>TapSum</span></div><p class="tagline">Remember. Count. Tap!</p><div class="loading-dots"><i></i><i></i><i></i></div><div class="startup-progress"><i style="width:76%"></i></div><strong class="progress-label">76%</strong><a class="skip-loading" href="${route('menu')}">Skip preview →</a></div>`;
 case 'menu': return `<div class="screen-content menu-screen">${brandHead('0')}<div class="menu-spacer"></div><div class="menu-title"><span class="eyelabel">A quick game for your number brain</span><h1>Remember.<br>Count. Tap.</h1><p>Each round adds a number to the running total. Reach it exactly before time runs out.</p></div><div class="menu-workbench">${tape('+5','+3','8','SAMPLE')}${playRail()}</div><div class="record-line"><span>Best score</span><strong>0</strong></div>${utility}</div>`;
 case 'help': return overlaySheet('<h2>How to play</h2>','<p>Each round shows a new signed number. Keep the running total in your head, then build to it with the place-value buttons.</p><ol><li>Remember every <b>+ or − number</b> as it appears.</li><li>Tap <b>+1, +10, +100 or +1000</b> to reach the total.</li><li>Match it exactly to score <b>10 points</b> and continue.</li></ol><p>Go over the total or run out of time and the run ends. Each round has a timer.</p>',`<a class="action-button primary" href="${route('menu')}">Got it</a>`,'menu');
 case 'leaderboard-loading': return overlaySheet('<h2>Leaderboard</h2>','<p class="muted">Loading player scores…</p><div class="loading-skeleton"><i></i><i></i><i></i></div>',`<div class="leader-tabs"><a class="selected" href="${route('leaderboard-loading')}">World</a><a href="${route('leaderboard-empty')}">My score</a></div><a class="action-button blue" href="${route('leaderboard-ranked')}">Show loaded example</a>`,'menu');
 case 'leaderboard-empty': return overlaySheet('<h2>Leaderboard</h2>','<div class="empty-medal">No rank</div><p class="empty-title">No scores yet</p><p>Play a round to set a score and appear here.</p>',`<div class="leader-tabs"><a class="selected" href="${route('leaderboard-empty')}">World</a><a href="${route('leaderboard-ranked')}">My score</a></div><a class="action-button primary" href="${route('gameplay-start')}">Play a round</a>`,'menu');
 case 'leaderboard-ranked': return overlaySheet('<h2>Leaderboard</h2>','<p class="sample-label">ILLUSTRATIVE EXAMPLE SCORES</p><div class="leader-tabs"><a class="selected" href="'+route('leaderboard-ranked')+'">World</a><a href="'+route('leaderboard-empty')+'">My score</a></div><div class="leader-head"><span>#</span><span>PLAYER</span><span>BEST</span></div><div class="leader-list">'+[['1','gold','Ari','240'],['2','silver','Maya','190'],['3','bronze','Noam','160'],['4','','You','70'],['5','','Rina','60'],['6','','Eli','40']].map(([rank,medal,name,score])=>`<div class="leader-row ${name==='You'?'you':''}"><span>${medal?`<img class="medal" src="${asset(`medal/${medal==='gold'?'1-gold':medal==='silver'?'2-silver':'3-bronze'}.svg`)}" alt="${medal} medal">`:rank}</span><span>${name}</span><strong>${score}</strong></div>`).join('')+'</div><p class="sample-note">Example values only. Live scores come from the game service.</p>',`<a class="action-button blue" href="${route('menu')}">Close leaderboard</a>`,'menu','leaderboard-underlay');
 case 'gameplay-start': return gameplay({round:'1',score:'0',delta:'+8',timerValue:'00:07',tapCount:2});
 case 'gameplay-warning': return gameplay({round:'18',score:'170',delta:'−6',timerValue:'00:01',warn:true,label:'TAKE AWAY',tapCount:7,history:['+12','+8','−4']});
 case 'pause': return `<div class="screen-content game-layout">${smallHead('18','170',false)}${timer('PAUSED',false,'−6','HIDDEN')}<div class="tape-before"><span>NUMBER HIDDEN WHILE PAUSED</span><b>Hidden</b></div>${increments}<div class="overlay-center"><section class="dialog-card pause-card"><span class="eyelabel">ROUND 18 · SCORE 170</span><h2>Paused</h2><p>Timer stopped. The number is hidden.</p><div class="pause-buttons"><a class="action-button primary" href="${route('gameplay-warning')}">Resume</a><button class="action-button blue" data-action="sound">Sound <span data-sound-state>On</span></button><a class="action-button danger" href="${route('end-quit')}">Quit run</a></div></section></div></div>`;
 case 'round-success': return gameplay({round:'4',score:'30',delta:'+8',timerValue:'00:04',tapCount:4,history:['+5','+3','−2'],success:true});
 case 'end-overshoot': return summary({reason:'overshoot',score:'70',round:'8',needed:'46',tapped:'50',recent:['+12','−4','+8'],best:'80',rank:'#124'});
 case 'end-timeout': return summary({reason:'timeout',score:'40',round:'5',needed:'32',tapped:'27',recent:['+6','+10','−3'],best:'50',rank:'#208'});
 case 'end-quit': return summary({reason:'quit',score:'30',round:'4',needed:'26',tapped:'18',recent:['+5','+3','−2'],best:'50',rank:'#351',compact:true});
 case 'end-new-best': return summary({reason:'timeout',score:'90',round:'10',needed:'54',tapped:'48',recent:['+12','−4','+8'],best:'90',rank:'…',newBest:true});
 case 'end-no-rank': return summary({reason:'overshoot',score:'40',round:'5',needed:'32',tapped:'34',recent:['+6','+10','−3'],best:'50',rank:'N/A'});
 case 'support': return `<div class="screen-content support-screen">${brandHead('0')}<div class="support-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 21S3 15.4 3 9.2C3 4.5 8.8 3 12 7c3.2-4 9-2.5 9 2.2 0 6.2-9 11.8-9 11.8Z"/></svg></div><span class="eyelabel">SUPPORT TAPSUM</span><h1>Keep the game going.</h1><p class="supporting">This button hands off to the Rehovot purchases plugin. The plugin supplies the native donation screen on supported devices.</p><div class="support-note"><b>Platform handoff</b><span>Payment options and confirmation are owned by the installed purchases plugin.</span></div><div class="pause-buttons"><a class="action-button primary" href="${route('menu')}">Return to menu</a><a class="text-button" href="${route('menu')}">Close</a></div></div>`;
 default: return '';
 }
}
function renderIndex(){
 const host=document.getElementById('screen-index'); if(!host)return;
 const groups=[...new Set(screens.map(s=>s.group))];
 host.innerHTML=groups.map(group=>`<div class="index-group"><h3>${group}</h3>${screens.filter(s=>s.group===group).map(s=>`<a class="index-link" href="${route(s.id)}"><span class="index-number">${String(screens.indexOf(s)+1)}</span><strong>${s.title}</strong><small>${s.description}</small><span class="index-arrow" aria-hidden="true">↗</span></a>`).join('')}</div>`).join('');
}
function renderPrototype(){
 const host=document.getElementById('game-screen'); if(!host)return;
 document.title=`${screen.title} · TapSum mockup`;
 document.getElementById('screen-label').textContent=`${String(currentIndex+1)} / ${screens.length} · ${screen.title}`;
 const previous=screens[(currentIndex-1+screens.length)%screens.length]; const next=screens[(currentIndex+1)%screens.length];
 document.getElementById('previous-screen').href=route(previous.id);document.getElementById('next-screen').href=route(next.id);
 host.innerHTML=stateContent(screen.id);
 host.dataset.screen=screen.id;
 document.querySelectorAll('[data-go]').forEach(el=>el.href=route(el.dataset.go));
 const soundBtns=document.querySelectorAll('[data-action="sound"]');
 soundBtns.forEach(b=>{b.setAttribute('aria-pressed','true');b.addEventListener('click',()=>{const enabled=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(enabled));document.querySelectorAll('[data-sound-state]').forEach(x=>x.textContent=enabled?'On':'Off');b.setAttribute('aria-label',`Sound ${enabled?'on':'off'}`)})});
 document.querySelectorAll('[data-tap]').forEach(b=>b.addEventListener('click',()=>{const pips=document.querySelector('[data-tap-pips]');const count=document.querySelector('[data-tap-count]');if(pips&&count){const n=pips.children.length+1;if(n<=12){pips.insertAdjacentHTML('beforeend','<i></i>');count.textContent=`${n} taps this round`}}}));
}
renderIndex();renderPrototype();
